  { business_name: "Queen City HVAC Solutions", website: "https://queencityhvac1.test", phone: "(336) 555-0101", city: "Greensboro", state: "NC", vertical: "HVAC" },
  { business_name: "Greensboro Comfort Air", website: "https://gso-comfortair2.test", phone: "(336) 555-0102", city: "Greensboro", state: "NC", vertical: "HVAC" },
  { business_name: "Triad Heating & Cooling Co", website: "https://triad-hvac3.test", phone: "(336) 555-0103", city: "Greensboro", state: "NC", vertical: "HVAC" },
  { business_name: "Piedmont Climate Control", website: "https://piedmontclimate4.test", phone: "(336) 555-0104", city: "Greensboro", state: "NC", vertical: "HVAC" },
  { business_name: "Gate City Air Systems", website: "https://gatecityair5.test", phone: "(336) 555-0105", city: "Greensboro", state: "NC", vertical: "HVAC" },
];
// Loud validation: never run empty silently
if (!candidates || candidates.length === 0) {
  throw new Error("ALERT: Source candidates fixture empty — aborting lead ingestion (would run silently)");
}
return [{ json: { candidates, candidate_count: candidates.length, source: "fixture_greensboro_hvac_demo" } }];

const input = $input.first().json;
let reason = "empty batch";
let candidates = input.candidates;
let lead_ids = input.lead_ids;
let candidate_count = input.candidate_count ?? (Array.isArray(candidates) ? candidates.length : 0);
let collected = input.collected_count ?? (Array.isArray(lead_ids) ? lead_ids.length : 0);
if (Array.isArray(candidates) && candidates.length === 0) {
  reason = "candidates==0 — source adapter returned empty";
} else if (Array.isArray(lead_ids) && lead_ids.length === 0) {
  reason = "collected lead_ids==0 — all creates deduped or failed";
} else if (candidate_count === 0) {
  reason = "candidates==0";
} else if (collected === 0) {
  reason = "collected lead_ids==0";
}
let msg = `🚨 *Lead Ingestion ALERT — Empty batch*\n`;
msg += `Reason: ${reason}\n`;
msg += `Source: n8n_ingestion (fixture Greensboro NC HVAC demo)\n`;
msg += `Candidates: ${candidate_count ?? 0} | Collected lead_ids: ${collected}\n`;
msg += `Workflow: Orbit - Lead Ingestion (daily 7 AM)\n`;
msg += `Action: Manual review required — system never runs empty silently.`;
console.log("ALERT ingestion empty: " + msg + " | reason=" + reason);
return { telegramMessage: msg, alertReason: reason, candidate_count, collected };
